static const char *setting_names[]={"Locked","Lock when owner leaves","Wired access","Everyone can open","Everyone can donate","Chest name","Description","Usable capacity","Opening behavior","Contents preview","Preview entries","Notification mode","Full notification","Donation notification","Withdrawal notification","Empty notification","Transaction notification"};
